query MerchantAuContextPreflight($country: CountryCode!, $after: String) {
  shop {
    id
    primaryDomain { marketWebPresence {
      id defaultLocale { locale published }
      alternateLocales { locale published }
      rootUrls { locale url }
    } }
  }
  shopLocales { locale primary published }
  markets(first: 50) {
    nodes {
      id name status
      conditions {
        conditionTypes
        regionsCondition {
          applicationLevel
          regions(first: 250) {
            nodes { __typename ... on MarketRegionCountry { code } }
            pageInfo { hasNextPage endCursor }
          }
        }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
  marketsResolvedValues(buyerSignal: { countryCode: $country }) {
    currencyCode
    catalogs(first: 50, after: $after) {
      nodes {
        id status publication { id }
        markets(first: 50) {
          nodes { id name status }
          pageInfo { hasNextPage endCursor }
        }
      }
      pageInfo { hasNextPage endCursor }
    }
    webPresences(first: 50) {
      nodes {
        id defaultLocale { locale published }
        alternateLocales { locale published }
        rootUrls { locale url }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
}
